#include <stdio.h>
#include <stdlib.h>

typedef struct {
    char tag[4];
    int val;
} Item;

int main(void)
{
    Item *items = malloc(3 * sizeof(Item));
    if (items == NULL)
        return 1;
    for (int i = 0; i < 3; i++) {
        items[i].tag[0] = 'A' + i;
        items[i].tag[1] = '\0';
        items[i].val = (i + 1) * 10;
    }
    Item *p = items + 1;
    p->val += items[2].val;
    p++;
    printf("%s %d %zu\n", p->tag, items[1].val, sizeof(Item));
    free(items);
    return 0;
}

